def find_missing_ranges(nums: list, lower: int, upper: int) -> list:
    res = []
    next_val = lower
    for num in nums:
        if num < next_val:
            continue
        if num > next_val:
            res.append([next_val, num - 1])
        next_val = num + 1
        if next_val > upper:
            break
    if next_val <= upper:
        res.append([next_val, upper])
    return res
```

